```python
import requests

class Skynet:
    def __init__(self):
        self.api_endpoint = "https://example.com/events"

    def get_my_events(self):
        try:
            response = requests.get(self.api_endpoint)
            if response.status_code == 200:
                return response.json()
            else:
                return None
        except requests.RequestException:
            return None

    def process_messages(self, event_data):
        messages = []
