class HTTPHeaderParser:
    def __init__(self):
        self.headers = {}
        self.cookies = {}

    def add_headers(self, header):
        """
        Parses the input headers and stores them in the self.headers and self.cookies dictionaries.

        Args:
        header (list): A list of strings representing the input headers.

        Returns:
        None
        """
        for line in header:
            if ': ' in line:
                k, v = line.split(': ', 1)
                if k.lower() == 'cookie':
                    cookies = v.split('; ')
                    for cookie in cookies:
                        cookie_key, cookie_value = cookie.split('=', 1)
