```python
from typing import List, Union

class StepToBeAdded:
    def __init__(self, description: str, duration: int, ingredients: List[str]):
        self.description = description
        self.duration = duration
        self.ingredients = ingredients

class Recipe:
    def __init__(self):
        self.steps = []

    def add_steps(self, steps: Union[List[StepToBeAdded], dict]):
        if isinstance(steps, list):
            for step in steps:
                self.add_step(step)
        elif isinstance(steps, dict):
            for step in steps.values():
                self.add_step(step)
