The `current_user` object represents the user currently logged in, and it has the following attributes:
- `is_authenticated`: A boolean indicating whether the user is authenticated.
- `is_admin`: A boolean indicating whether the user has administrative privileges.

The `request` object represents the current HTTP request, and it has the `endpoint` attribute, which indicates the endpoint being accessed.

Your task is to complete the `role_required` decorator so that it restricts access to functions based on the user's role.

```python
from functools import wraps

class User:
    def __init__(self, is_authenticated, is_admin):
        self.is_authenticated = is_authenticated
        self.is_admin = is_admin

current_user = User(is_authenticated=True, is_admin=True)

class Request:
    def __init__(self, endpoint):
        self.endpoint = endpoint

request = Request(endpoint='admin_dashboard')

def role_required(role):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if current_user.is_authenticated:
                if current_user.is_admin and role == 'admin' and 'admin' in request.endpoint:
                    return f(*args, **kwargs)
                elif not current_user.is_admin and role == 'user':
                    return f(*args, **kwargs)
                else:
                    return "Access Denied"
            else:
                return "Access Denied"
        return decorated_function
    return decorator

@role_required('admin')
def admin_dashboard():
    return "Welcome to the admin dashboard"

@role_required('user')
def user_profile():
    return "Welcome to your profile page"
```

