Your task is to complete the implementation of the Vector2 class by adding the necessary methods to support the specified operations.

```python
class Vector2:
    def __init__(self, x, y):
        self._x = x
        self._y = y

    def __add__(self, other):
        return Vector2(self._x + other._x, self._y + other._y)

    def __sub__(self, other):
        return Vector2(self._x - other._x, self._y - other._y)

    def __mul__(self, other):
        if isinstance(other, Vector2):
            return Vector2(self._x * other._x, self._y * other._y)
        else:
            return Vector2(self._x * other, self._y * other)

    def __rmul__(self, other):
        return self.__mul__(other)

    def __truediv__(self, other):
        if isinstance(other, Vector2):
            return Vector2(self._x / other._x, self._y / other._y)
        else:
            return Vector2(self._x / other, self._y / other)

    def __rdiv__(self, other):
        if hasattr(other, '__len__'):
            return Vector2(other[0] / self._x, other[1] / self._y)

