class CookieManager:
    def __init__(self, cookies_path):
        self.cookies_path = cookies_path

    def set_cookie(self, name, value, expiration=None):
        if expiration is not None:
            expiration_time = time.time() + expiration
        else:
            expiration_time = None
        self.cookies_path[name] = (value, expiration_time)

    def get_cookie(self, name):
        if name in self.cookies_path:
            value, expiration = self.cookies_path[name]
            if expiration is None or time.time() < expiration:
                return value
        return None

    def delete_cookie(self, name):
        if name in self.cookies_path:
            del self.cookies_path[name]
