```python
import cesiumpy.color
import unittest

class Color:
    def __init__(self, color_name):
        self.color_name = color_name

    @property
    def script(self):
        return f"Cesium.Color.{self.color_name}"

    @classmethod
    def maybe(cls, color_name):
        valid_colors = ["RED", "GREEN", "BLUE"]  # Valid color names
        if color_name.upper() in valid_colors:
            return cls(color_name)
        else:
            raise ValueError(f"Unable to convert to Color instance: {color_name}")

    def __repr__(self):
        return f"Color.{self.color_name}"

class TestColor(unittest.TestCase):
    def test_color_conversion(self):
        blue = Color.maybe('BLUE')
        self.assertEqual(repr(blue), "Color.BLUE")
        self.assertEqual(blue.script, "Cesium.Color.BLUE")

        red = Color.maybe('RED')
        self.assertEqual(repr(red), "Color.RED")
        self.assertEqual(red.script, "Cesium.Color.RED")

        with self.assertRaises(ValueError) as context:
            invalid_color = Color.maybe('INVALID')
        self.assertEqual(str(context.exception), "Unable to convert to Color instance: INVALID")

if __name__ == '__main__':
    unittest.main()
```

