You are tasked with implementing a stack data structure using a singly linked list. The stack should support the following operations:

1. `push(val)`: Add a new element `val` to the top of the stack.
2. `pop()`: Remove and return the element at the top of the stack. If the stack is empty, return None.
3. `peek()`: Return the element at the top of the stack without removing it. If the stack is empty, return None.
4. `is_empty()`: Return True if the stack is empty, False otherwise.

You are given the following code snippet for the `Stack` class, which includes a method to display the elements of the stack and a method to check if the stack is empty:

```python
class Node:
    def __init__(self, data: int):
        self.data = data
        self.next = None

class Stack:
    def __init__(self):
        self.top = None
        self.size = 0

    def push(self, val: int) -> None:
        new_node = Node(val)
        new_node.next = self.top
        self.top = new_node
        self.size += 1

    def pop(self) -> int:
        if self.is_empty():
            return None
        else:
            popped = self.top.data
            self.top = self.top.next
            self.size -= 1
            return popped

    def peek(self) -> int:
        if self.is_empty():
            return None
        else:
            return self.top.data

    def display(self) -> None:
        ptr = self.top
        while ptr is not None:
            print(ptr.data)
            ptr = ptr.next

    def is_empty(self) -> bool:
        return self.size == 0
```

