class FileError(Exception):
    pass

class DataHandler:
    def save_data(self, data, filename):
        try:
            with open(filename, 'wb') as file:
                file.write(pickle.dumps(data))
        except IOError:
            raise FileError("Unable to save data to file")

    def load_data(self, filename):
