```python
import cherrypy

class GreetingApp:
    @cherrypy.expose
    def index(self):
        cookie = cherrypy.request.cookie.get('user', 'Unknown')
        return f"<h1>Hello! How are you?</h1> User: {cookie.value}"

    @cherrypy.expose
    def set(self):
        cookie = cherrypy.response.cookie
        cookie['user'] = 'CherryPyUser'
        return "<h1>Cookie set successfully</h1>"

if __name__ == '__main__':
    cherrypy.quickstart(GreetingApp())
```

