Your implementation should adhere to the provided code structure and utilize the `requests` library for making HTTP requests.

```python
import requests

class Base:
    def __init__(self, auth_token):
        self.auth_token = auth_token

    def get_url(self, extra=''):
        base_url = 'https://api.example.com'
        return base_url + self.__endpoint__ + extra

    def validate_response(self, response):
        return response.status_code == 200

    def status_code_to_exception(self, status_code):
        if status_code == 401:
            return AuthenticationError()
        elif status_code == 404:
            return ResourceNotFoundError()
        else:
            return APIError()

    def delete(self, resource_id):
        url = self.get_url(extra=str(resource_id))
        headers = {'X-Auth-Token': self.auth_token}
        response = requests.delete(url, headers=headers)
        if not self.validate_response(response):
            exception = self.status_code_to_exception(response.status_code)
            exception.message = response.text
            raise exception


class Logs(Base):
    __endpoint__ = '/log/'
    __resourcename__ = 'log'

class AuthenticationError(Exception):
    pass

class ResourceNotFoundError(Exception):
    pass

class APIError(Exception):
    pass
