```python
class Proxy:
    def __init__(self, proxied_object):
        self.proxied_object = proxied_object
        self.is_chaperone_flag = False
        self.is_impersonator_flag = False

    def is_proxy(self):
        return self.is_chaperone() or self.is_impersonator()

    def is_chaperone(self):
        return self.is_chaperone_flag

    def is_impersonator(self):
        return self.is_impersonator_flag

    def get_proxied(self):
        if self.is_proxy():
            return self.proxied_object
        else:
            return None
```

