typedef HandleDecryptedQrCodeCallback = Future<void> Function(
    BuildContext context, String qrCodeString, String encryptedQrCode);

class AccountLinkingDecryptionSection extends StatefulWidget {
  const AccountLinkingDecryptionSection({
    Key? key,
    required this.encryptedQrCode,
    required this.handleDecryptedQrCodeCallback,
  }) : super(key: key);

  final String encryptedQrCode;
  final HandleDecryptedQrCodeCallback handleDecryptedQrCodeCallback;

  @override
  AccountLinkingDecryptionSectionState createState() =>
      AccountLinkingDecryptionSectionState();
}

class AccountLinkingDecryptionSectionState
    extends State<AccountLinkingDecryptionSection> {
  late AppLocalizations _l10n;
  bool hasError = false;
  final int maxFailedAttempts = 2;
  int failedAttempts = 0;
  bool _encryptionInProgress = false;

  @override
  void didChangeDependencies() {
    _l10n = AppLocalizations.of(context)!;
    super.didChangeDependencies();
  }

  @override
  Widget build(BuildContext context) {
    return ChangeNotifierProvider<DateOfBirthInputModel>(
        create: (_) => DateOfBirthInputModel(null),
        builder: (context, child) => _buildBody(context));
  }

  Widget _buildBody(BuildContext context) {
    final dobInputModel = Provider.of<DateOfBirthInputModel>(context);

    return SizedBox(
      height: PageSizeExpert.pageHeight(context),
      width: PageSizeExpert.pageWidth(context),
      child: Padding(
        padding: theme.commonEdgeInsets,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const SizedBox(height: theme.largeSpacing),
            Text(
              _l10n.accountLinking_QrCodeDecryptionScreenTitle,
              style: Theme.of(context).textTheme.headline1,
            ),
            const SizedBox(height: theme.extraSmallSpacing),
            Text(
              _l10n.accountLinking_QrCodeDecryptionScreenDescription,
            ),
            const SizedBox(height: theme.extraLargeSpacing),
            Text(
              _l10n.accountLinking_QrCodeDecryptionDateOfBirthEntryHeader,
              style: Theme.of(context).textTheme.headline3,
            ),
            const SizedBox(height: theme.smallSpacing),
            DateOfBirthInput(dobInputModel: dobInputModel),
            const SizedBox(height: theme.smallSpacing),
            if (hasError)
              ErrorDisplay(
                  errorMessage:
                      _l10n.accountLinking_QrCodeDecryptionErrorMessage),
            const Spacer(),
            ElevatedButton(
              onPressed: _decryptButtonCallback(dobInputModel, context),
              child: Text(
                _l10n.general_confirmButtonLabel,
              ),
            ),
            const SizedBox(height: theme.extraSmallSpacing),
            _cancelButton(),
          ],
        ),
      ),
    );
  }

  VoidCallback? _decryptButtonCallback(
      DateOfBirthInputModel dobInputModel, BuildContext context) {
    if (_encryptionInProgress) {
      // disable decrypt button
      return null;
    } else {
      return () {
        if (dobInputModel.isValid()) {
          setState(() {
            _encryptionInProgress = true;
          });
          _decrypt(dobInputModel, widget.encryptedQrCode)
              .then((decryptedQrCode) => widget.handleDecryptedQrCodeCallback(
                  context, decryptedQrCode, widget.encryptedQrCode))
              .onError((error, stackTrace) {
            handleDecryptionErrorCase(context);
          });
        }
      };
    }
  }

  Future<String> _decrypt(
      DateOfBirthInputModel dobInputModel, String encryptedQrCode) async {
    String dobString = buildDateOfBirthString(dobInputModel);
    return await QrCodeDecrypter.decryptMessage(dobString, encryptedQrCode);
  }

  void handleDecryptionErrorCase(BuildContext context) {
    if (failedAttempts + 1 > maxFailedAttempts) {
      context.read<AccountLinkingStateManager>().updateQrDecryptionFailed(true);
    } else {
      setState(() {
        hasError = true;
        failedAttempts += 1;
        _encryptionInProgress = false;
      });
    }
  }

  OutlinedButton _cancelButton() {
    return OutlinedButton(
      onPressed: () => context.read<AccountLinkingStateManager>().deleteState(),
      style: theme.cancelButtonStyle(),
      child: Text(
        _l10n.general_cancelButtonLabel,
      ),
    );
  }

  String buildDateOfBirthString(DateOfBirthInputModel dobInputModel) {
    String dobString =
        '${dobInputModel.year}-${dobInputModel.month}-${dobInputModel.day}';
    return dobString;
  }
}
