% Laplacian kernel function for GOA2 algorithm
function [Klap] = laplacianKernel(X, c, s)
    % X: M * N matrix (M observations, N dimensions)
    % c: centers of kernel function (clusters) 
    % s: width of kernel function (scaling parameter)

    % Number of centers (clusters)
    Nc = size(c, 1);
    M = size(X, 1);
    Klap = zeros(M, Nc);

    for i = 1:Nc
        d = sqrt(sum((X - repmat(c(i, :), M, 1)).^2, 2));
        Klap(:, i) = exp(-d./s);
    end
