You are provided with a skeleton code for the decorator and a sample function `fetch` that makes API requests. The `fetch` function takes a dictionary `data` containing the URL, headers, and body for the request. Your task is to complete the `handle_rate_limits` decorator to enforce the rate limit for the `fetch` function.

```python
import time

def handle_rate_limits(rate_limit):
    def decorator(func):
        last_called = 0

        def wrapper(*args, **kwargs):
            nonlocal last_called
            elapsed_time = time.time() - last_called
            if elapsed_time < 1 / rate_limit:
                time.sleep(1 / rate_limit - elapsed_time)
            last_called = time.time()
            return func(*args, **kwargs)

        return wrapper

    return decorator

class APIClient:
    def __init__(self):
        self.client = SomeHTTPClient()

    @handle_rate_limits(rate_limit=5)  # Example rate limit of 5 requests per second
    def fetch(self, data):
        """
        :param data: {}
            Raw request
        :return: response
            Fetch with client
        """
        return self.client.fetch(
            data["url"], headers=data["headers"], body=data["body"]
        )
